        array('n'=>'s1614_e11_skydelis_35438','u'=>admin_url('admin.php?page=ps-desk&eile=surinkti&atidaryti=35438'),'w'=>1400,'eval'=>"(async()=>{await new Promise(r=>setTimeout(r,2500)); return {pastaba:(document.getElementById('skPastaba')||{innerText:''}).innerText.replace(/\\s+/g,' ').slice(0,320),locks:[...document.querySelectorAll('#skEil .lock')].map(x=>x.innerText),siunta:(document.getElementById('skSiuntaT')||{innerText:''}).innerText.replace(/\\s+/g,' ').slice(0,200),v:(document.getElementById('skV')||{innerText:''}).innerText.replace(/\\s+/g,' ')}; })()"),
        array('n'=>'s1614_e11_forma_35431','u'=>admin_url('admin.php?page=ps-desk&eile=visi&q=35431&atidaryti=35431'),'w'=>1400,'click'=>'#skRed','eval'=>"({forma:!!document.getElementById('skRedF'),laukai:[...document.querySelectorAll('#skRedF input:not([type=hidden]),#skRedF select')].map(x=>x.name+':'+x.type),notes:document.querySelectorAll('#skRedF .dl-note').length})")
      );
