      $x=wc_get_order(35438); $eil=array(); foreach($x->get_items() as $iid=>$it){ $eil[$iid]=array('k'=>(string)$it->get_meta('_ps_kelias'),'src'=>(string)$it->get_meta('_ps_source'),'rq'=>(string)$it->get_meta('_ps_av_reduced_qty'),'iss'=>(string)$it->get_meta('_ps_issiusta'),'ats'=>(string)$it->get_meta('_ps_atsaukta')); }
      $o['meta']=array('st'=>$x->get_status(),'eil'=>$eil,'baigtos'=>(string)$x->get_meta('_ps_dalys_baigtos'),'iss'=>(string)$x->get_meta('_ps_dalys_issiusta'),'senos'=>(string)$x->get_meta('_ps_siuntos_senos'),'grizta'=>(string)$x->get_meta('_ps_siunta_grizta'),'is_naujo'=>(string)$x->get_meta('_ps_dalys_is_naujo'),'ats'=>(string)$x->get_meta('_ps_dalys_atsaukta'),'type'=>(string)$x->get_meta('_ps_order_type'),'ship'=>(string)$x->get_meta('_ps_shipments'));
      $nt=wc_get_order_notes(array('order_id'=>35438,'limit'=>2)); $o['pastabos']=array_map(function($x){ return mb_substr($x->content,0,420); },$nt);
