      $o['ks']=$ks(35438); $o['ks_html_busenos']=array(); $h=Petshop_Kliento_Siuntos::html(Petshop_Darbalaukis::kliento_siuntos($x)); preg_match_all('/<b>([^<]*)<\/b><span class="ps-siunta__busena">([^<]*)</su',$h,$m); $o['ks_html_busenos']=array_map(null,$m[1],$m[2]);
      $o['stock']=array('19708'=>get_post_meta(19708,'_stock',true),'16889_own'=>get_post_meta(16889,'_own_stock_qty',true)); $o['sk_po']=$sk(35438);
